/**
 * Every country and territory on the world tour map, as SVG path data.
 *
 * Boundaries: Natural Earth 1:50m admin-0 countries (public domain). Projected with Miller into a
 * 360 × 176.3 viewBox (x = longitude + 180), rings unwrapped across the antimeridian, and simplified
 * to within ~0.25 map units. Sea areas and Antarctica are left out. Regenerate from the source rather
 * than editing the paths by hand.
 *
 * Draw each path three times, shifted by -360, 0 and +360 in x, so that countries crossing the
 * antimeridian (Russia's east, Fiji) appear at both edges of the map.
 */

export const WORLD_WIDTH = 360
export const WORLD_HEIGHT = 176.3

export const CONTINENT_BN = {
  Africa: 'আফ্রিকা',
  Asia: 'এশিয়া',
  Europe: 'ইউরোপ',
  NorthAmerica: 'উত্তর আমেরিকা',
  SouthAmerica: 'দক্ষিণ আমেরিকা',
  Oceania: 'ওশেনিয়া',
} as const
export type Continent = keyof typeof CONTINENT_BN

export interface Country {
  id: string
  /** English name. */
  name: string
  /** Bangla name, from Natural Earth. */
  nameBn: string
  continent: Continent
  /** Other names people search for. */
  aliases: readonly string[]
  /** A point inside the country, in map units, for the pin on the map. */
  label: readonly [number, number]
  /** Closed SVG path (one subpath per ring). */
  d: string
}

